import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { midiBytesToNotes } from '../lib/midi-import';

// Fixture generated by tests/fixtures/make-fixture.ts:
// 48 (0 s, 1 s long), 64 and 67 (0.5 s, 0.5 s long), 72 (2 s, 1.5 s long).
const bytes = readFileSync(new URL('./fixtures/small.mid', import.meta.url));
// 0 s = beat 0, 10 s = beat 20 → 2 beats per second.
const anchors = [{ mediaTimeMs: 0, beat: 0 }, { mediaTimeMs: 10_000, beat: 20 }];

test('fixture yields the expected notes, ordered by time then pitch', () => {
  const notes = midiBytesToNotes(bytes, anchors);
  assert.equal(notes.length, 4);
  assert.deepEqual(notes.map(n => n.midi), [48, 64, 67, 72]);
  assert.deepEqual(notes.map(n => n.id), ['n0001', 'n0002', 'n0003', 'n0004']);
});

test('seconds become beats through the sync anchors', () => {
  const [low, e, g, high] = midiBytesToNotes(bytes, anchors);
  assert.equal(low.startBeat, 0);
  assert.equal(low.durationBeats, 2);
  assert.equal(e.startBeat, 1);
  assert.equal(e.durationBeats, 1);
  assert.equal(g.startBeat, 1);
  assert.equal(high.startBeat, 4);
  assert.equal(high.durationBeats, 3);
});

test('hand is left below MIDI 60, right otherwise', () => {
  const hands = midiBytesToNotes(bytes, anchors).map(n => n.hand);
  assert.deepEqual(hands, ['left', 'right', 'right', 'right']);
});

test('a different anchor map rescales beats', () => {
  const slow = [{ mediaTimeMs: 0, beat: 0 }, { mediaTimeMs: 10_000, beat: 10 }];
  assert.equal(midiBytesToNotes(bytes, slow)[3].startBeat, 2);
});
